import React, { useState } from "react";
import "./App.css";
import { 
  Gamepad2, Globe, ChevronDown, User, LogOut, LayoutDashboard, UserCircle, 
  X, BookOpen, Trophy, Star, TrendingUp, Zap, ChevronRight, ChevronLeft 
} from 'lucide-react'; 
import { Routes, Route, useNavigate, useLocation } from "react-router-dom";

// Components
import Login from "./Login";
import Signup from "./Signup";
import Dashboard from "./components/Dashboard"; 
import Chatbot from "./components/Chatbot";

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false); 
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  
  // --- NEW: State for Demo Modal ---
  const [showDemo, setShowDemo] = useState(false);
  
  const navigate = useNavigate();
  const location = useLocation();

  const handleLogout = () => {
     setIsLoggedIn(false);
     setShowProfileMenu(false);
     navigate("/");
  };

  return (
    <div className="app-root">
      
      {/* --- NAVBAR --- */}
      {!location.pathname.includes("/login") && !location.pathname.includes("/signup") && (
        <nav className="navbar">
           <div className="logo" onClick={() => navigate("/")}><Gamepad2 size={32} /> VidyaQuest</div>
           
           <div className="nav-links">
              <span onClick={() => navigate("/")}>Home</span>
              <span onClick={() => navigate(isLoggedIn ? "/dashboard" : "/login")}>Subjects</span>
              <span>Games</span>
              <span>Leaderboard</span>
           </div>

           <div className="auth-buttons">
              <button className="btn-secondary">
                 <Globe size={16}/> English
              </button>

              {!isLoggedIn ? (
                 <>
                    <span style={{fontWeight:'600', cursor:'pointer', marginRight:'10px'}} onClick={() => navigate("/login")}>Sign In</span>
                    <button className="btn-primary" onClick={() => navigate("/signup")}>Sign Up</button>
                 </>
              ) : (
                 <div style={{position:'relative'}}>
                    <button className="btn-user" onClick={() => setShowProfileMenu(!showProfileMenu)}>
                       <User size={18}/> srija <ChevronDown size={14}/>
                    </button>
                    
                    {showProfileMenu && (
                       <div className="profile-menu">
                          <div className="menu-item" onClick={() => {navigate("/dashboard"); setShowProfileMenu(false);}}>
                             <UserCircle size={18}/> Profile
                          </div>
                          <div className="menu-item" onClick={() => {navigate("/dashboard"); setShowProfileMenu(false);}}>
                             <LayoutDashboard size={18}/> Dashboard
                          </div>
                          <div className="menu-item danger" onClick={handleLogout}>
                             <LogOut size={18}/> Sign Out
                          </div>
                       </div>
                    )}
                 </div>
              )}
           </div>
        </nav>
      )}

      {/* --- ROUTES --- */}
      <Routes>
        <Route path="/" element={
           <LandingPage 
              isLoggedIn={isLoggedIn} 
              navigate={navigate} 
              onWatchDemo={() => setShowDemo(true)} // Pass the open function
           />
        } />
        
        <Route path="/login" element={<Login onSuccess={() => { setIsLoggedIn(true); navigate("/"); }} />} />
        <Route path="/signup" element={<Signup onSuccess={() => navigate("/login")} />} />
        <Route path="/dashboard" element={<Dashboard />} />
      </Routes>

      {/* Chatbot */}
      {!location.pathname.includes("/login") && !location.pathname.includes("/signup") && <Chatbot />}

      {/* --- DEMO MODAL (The Slideshow) --- */}
      {showDemo && <DemoModal onClose={() => setShowDemo(false)} />}
      
    </div>
  );
}

// --- LANDING PAGE COMPONENT ---
